import{_ as t}from"./chunks/console-releases.Bzh_r7S0.js";import{_ as a,o as s,c as o,a3 as r}from"./chunks/framework.DhF4LrUq.js";const u=JSON.parse('{"title":"Work with releases","description":"Work with releases - create one from the CLI, follow it on the release dashboard, and read its lifecycle.","frontmatter":{"description":"Work with releases - create one from the CLI, follow it on the release dashboard, and read its lifecycle."},"headers":[],"relativePath":"how-to/console/releases.md","filePath":"how-to/console/releases.md"}'),i={name:"how-to/console/releases.md"};function n(l,e,h,d,p,c){return s(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="work-with-releases" tabindex="-1">Work with releases <a class="header-anchor" href="#work-with-releases" aria-label="Permalink to &quot;Work with releases&quot;">​</a></h1><p>A release is the governed act of distributing one version&#39;s READY artifacts to a set of tenants on a starting ring. Releases are created from the CLI or CI (the Console is their dashboard, not their creator) and driven through a fixed <a href="/shipperdog/snapshot/concepts/release-lifecycle">lifecycle</a>.</p><p><img src="'+t+`" alt="The Releases screen"></p><h2 id="create-a-release" tabindex="-1">Create a release <a class="header-anchor" href="#create-a-release" aria-label="Permalink to &quot;Create a release&quot;">​</a></h2><p>From the <a href="/shipperdog/snapshot/how-to/automation/cli-reference">CLI</a>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shipperdog</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> banking</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 7.12.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --tenants</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TENANT_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ring</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> engineering</span></span></code></pre></div><ul><li><strong>Artifacts select themselves</strong> — the newest READY artifact per platform of that version. Override one platform with <code>--artifact ios=&lt;artifactId&gt;</code> when a specific build must ship.</li><li><strong><code>--tenants</code></strong> takes the target tenant ids (comma-separated, repeatable); <strong><code>--groups</code></strong> optionally narrows each tenant to tester groups (<code>tenantId=groupId</code> or a bare group applying to every tenant).</li><li><strong><code>--ring</code></strong> is the starting ring — one of <code>engineering</code>, <code>qa</code>, <code>tenant-pilot</code>, <code>uat</code>, <code>production</code> until your organization <a href="/shipperdog/snapshot/how-to/console/rings-and-promotion">customizes the vocabulary</a>.</li><li><strong><code>--environment</code></strong> optionally pins the deployment context; every target tenant must sit inside its assignments.</li></ul><p>The release is born <strong>DRAFT</strong> and answers with its quotable id (<code>R-1028</code>) — the reference every later command accepts.</p><h2 id="find-releases-in-the-console" tabindex="-1">Find releases in the Console <a class="header-anchor" href="#find-releases-in-the-console" aria-label="Permalink to &quot;Find releases in the Console&quot;">​</a></h2><ol><li>Open <strong>Releases</strong> and pick the application — the listing is per-application.</li><li>Filter server-side by <strong>Status</strong>, <strong>Version</strong>, and <strong>Target tenant</strong>; the <strong>Ring</strong> box and <strong>Search</strong> filter the loaded rows client-side. <strong>Load more</strong> pages.</li><li>Click <strong>View</strong> on a release to open its dashboard — the deep-linkable page everything below lives on.</li></ol><h2 id="read-the-release-dashboard" tabindex="-1">Read the release dashboard <a class="header-anchor" href="#read-the-release-dashboard" aria-label="Permalink to &quot;Read the release dashboard&quot;">​</a></h2><p>One screen, every block you need to judge a release:</p><table tabindex="0"><thead><tr><th>Block</th><th>What it answers</th></tr></thead><tbody><tr><td>Lifecycle</td><td>The current status and the legal next transitions as buttons</td></tr><tr><td>Artifacts</td><td>The per-platform artifact pins — sha256, build, size freeze at APPROVED</td></tr><tr><td><a href="/shipperdog/snapshot/how-to/console/quality-gates">Quality gates</a></td><td>The ring&#39;s expected gate set with live states</td></tr><tr><td><a href="/shipperdog/snapshot/how-to/console/approvals">Approvals</a></td><td>The bound policy&#39;s rounds, waiting-on list, and signatures</td></tr><tr><td><a href="/shipperdog/snapshot/how-to/console/feedback-triage">Feedback</a></td><td>Tester reports and the open-critical count</td></tr><tr><td>Distribution</td><td>Targets, ring, the promotion controls, and the store channels</td></tr><tr><td>State timeline</td><td>Every crossing with its actor and moment</td></tr><tr><td>Promotion timeline</td><td>Every ring hop and every refusal with its complete blocker list</td></tr></tbody></table><p><strong>Compare</strong> (top right) diffs this release&#39;s frozen manifest against another APPROVED release of the same application — the answer to &quot;what exactly changed since the last one we shipped?&quot;</p><h2 id="drive-the-lifecycle" tabindex="-1">Drive the lifecycle <a class="header-anchor" href="#drive-the-lifecycle" aria-label="Permalink to &quot;Drive the lifecycle&quot;">​</a></h2><p>The Lifecycle block offers only the state machine&#39;s legal edges — the server refuses every other crossing. Failed and rolled-back crossings demand a reason in the dialog (&quot;the release explains itself&quot;).</p><ul><li>To walk a release forward hop by hop, see <a href="/shipperdog/snapshot/how-to/console/rings-and-promotion">rings and promotion</a>.</li><li>To widen a production rollout in stages, see <a href="/shipperdog/snapshot/how-to/console/staged-rollout">staged rollout</a>.</li><li>To undo one, see <a href="/shipperdog/snapshot/how-to/console/rollback">roll back a release</a>.</li></ul><p>The same moves exist as CLI verbs (<code>release transition</code>, <code>release promote</code>) for pipelines — see the <a href="/shipperdog/snapshot/how-to/automation/cli-reference">CLI reference</a>.</p><p><strong>Related guides:</strong> <a href="/shipperdog/snapshot/how-to/console/approvals">approvals</a> · <a href="/shipperdog/snapshot/how-to/console/rings-and-promotion">rings and promotion</a> · <a href="/shipperdog/snapshot/concepts/release-lifecycle">release lifecycle concepts</a></p>`,19)])])}const k=a(i,[["render",n]]);export{u as __pageData,k as default};
